// src/app/waveAnimation/index.js

const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');
const animationToggle = document.getElementById('animation-toggle');

const width = 240;
const height = 100;
const bars = 16;
const frameInterval = 1000 / 15;

const barWidth = 1;
const gap = 6;
const minHeight = 3;
const maxHeight = 75;

const totalWidth = bars * barWidth + (bars - 1) * gap;
const startX = (width - totalWidth) / 2;
const baseline = height - 10;

let animationEnabled = false;
let audioCtx;
let analyser;
let dataArray;
let source;
let audioElement;
let timer = null;

canvas.width = width;
canvas.height = height;
canvas.hidden = true;


animationToggle.checked = false;

// ===== Отрисовка =====
function draw(active = false) {
    ctx.clearRect(0, 0, width, height);
    ctx.fillStyle = '#55c8ff';

    const readAudio = active && analyser && dataArray;

    if (readAudio) {
        analyser.getByteFrequencyData(dataArray);
    }

    for (let i = 0; i < bars; i++) {
        let value = 0;

        if (readAudio) {
            const index = Math.floor(
                i * dataArray.length / bars
            );

            value = dataArray[index] / 255;
        }

        const barHeight =
            minHeight + value * (maxHeight - minHeight);

        ctx.fillRect(
            startX + i * (barWidth + gap),
            baseline - barHeight,
            barWidth,
            barHeight
        );
    }
}

// ===== Остановка =====
function stopAnimation() {
    if (timer !== null) {
        clearTimeout(timer);
        timer = null;
    }

    if (animationEnabled && !document.hidden) {
        draw();
    }
}

// ===== Цикл анимации =====
function tick() {
    timer = null;

    if (!animationEnabled || document.hidden) return;

    if (
        !audioElement ||
        audioElement.paused ||
        audioElement.ended
    ) {
        draw();
        return;
    }

    draw(true);
    timer = setTimeout(tick, frameInterval);
}

// ===== Запуск =====
function startAnimation() {
    if (
        !animationEnabled ||
        timer !== null ||
        !audioElement ||
        audioElement.paused ||
        audioElement.ended ||
        document.hidden
    ) {
        return;
    }

    tick();
}

// ===== Возобновление AudioContext =====
function resumeAudioContext() {
    if (audioCtx?.state === 'suspended') {
        audioCtx.resume().catch(error => {
            console.error(
                'Не удалось запустить AudioContext:',
                error
            );
        });
    }
}

function onPlaying() {
    resumeAudioContext();
    startAnimation();
}

// ===== Подключение звука =====
export default function initAudio(audio) {
    if (audioElement === audio) {
        resumeAudioContext();
        startAnimation();
        return;
    }

    if (audioElement) {
        console.warn(
            'Для переключения станции меняй src существующего audio.'
        );
        return;
    }

    const AudioContextClass =
        window.AudioContext || window.webkitAudioContext;

    if (!AudioContextClass) return;

    audioCtx = new AudioContextClass();

    analyser = audioCtx.createAnalyser();
    analyser.fftSize = 64;
    analyser.smoothingTimeConstant = 0.8;

    dataArray = new Uint8Array(analyser.frequencyBinCount);

    source = audioCtx.createMediaElementSource(audio);
    source.connect(analyser);
    analyser.connect(audioCtx.destination);

    audioElement = audio;

    audio.addEventListener('playing', onPlaying);
    audio.addEventListener('pause', stopAnimation);
    audio.addEventListener('ended', stopAnimation);
    audio.addEventListener('waiting', stopAnimation);
    audio.addEventListener('error', stopAnimation);
    audio.addEventListener('emptied', stopAnimation);

    resumeAudioContext();
    startAnimation();
}

// ===== Скрытая вкладка =====
document.addEventListener('visibilitychange', () => {
    if (document.hidden) {
        stopAnimation();
    } else {
        startAnimation();
    }
});

// ===== Переключатель анимации =====
animationToggle.addEventListener('change', () => {
    animationEnabled = animationToggle.checked;
    canvas.hidden = !animationEnabled;

    if (animationEnabled) {
        draw();
        resumeAudioContext();
        startAnimation();
    } else {
        stopAnimation();
        ctx.clearRect(0, 0, width, height);
    }
});

